/* @autogenerated */
import { themeProjectionToValue } from './theme.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('themeProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    tenant: { $ref: 'ref-tenant' },
    name: 'value-name',
    isDefault: 'value-isDefault',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(themeProjectionToValue(null)).toBeNull();
    expect(themeProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(themeProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      tenant: () => ({ uid: 'ref-tenant' }),
      name: 'value-name',
      isDefault: 'value-isDefault',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(themeProjectionToValue(projection)).toEqual(value);
  });
});
